package cn.bidcheck.document.word;

import cn.bidcheck.domain.Domain;
import com.aspose.words.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.zip.*;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.document.word.WordRenderSupport.*;

class WordRenderingServiceTest {
    @TempDir Path temp;
    WordRenderingService service(String license){return new WordRenderingService(temp,license,true,500,30,"",(a,b,c)->{fail("Unlicensed service must not start renderer");return "ERROR";});}
    Domain.Document doc(String project,String id,int version,String hash,List<Domain.Page> pages){return new Domain.Document(id,project,"BID","sample.docx",version,hash,"",pages,List.of());}
    @Test void absentLicenseNeverCreatesEvaluationArtifacts(){var s=service("");var result=s.layout(null,null);assertEquals("LICENSE_REQUIRED",result.get("status"));assertEquals(false,result.get("usableForEvidence"));assertEquals(List.of(),result.get("spans"));assertEquals(false,s.configuration().get("licensed"));assertFalse(Files.exists(temp.resolve("word-renderings")));assertThrows(IOException.class,()->s.renderedPdf(null,null));}
    @Test void invalidLicenseIsExplicitAndNeverLeaksPathOrContent()throws Exception{Path license=temp.resolve("private-license.lic");Files.writeString(license,"not-a-valid-license-private-marker");var s=service(license.toString());assertEquals("LICENSE_INVALID",s.layout(null,null).get("status"));String json=JSON.writeValueAsString(s.configuration());assertFalse(json.contains("private-marker"));assertFalse(json.contains(license.toString()));assertEquals(s.identity(),s.identity());}
    @Test void disabledModeAndConfigurationLimitsAreExplicit(){var s=new WordRenderingService(temp,"",false,500,30,"",(a,b,c)->"ERROR");assertEquals("DISABLED",s.layout(null,null).get("status"));assertThrows(IllegalArgumentException.class,()->new WordRenderingService(temp,"",true,1001,30,"",null));assertThrows(IllegalArgumentException.class,()->new WordRenderingService(temp,"",true,500,301,"",null));assertThrows(IOException.class,()->s.renderPage(null,null,0));}
    @Test void cacheKeysIncludeProjectVersionAndParsedBlockIdentity(){var pages=List.of(new Domain.Page(1,"示例正文","BLOCK","POI_NATIVE",""));var a=doc("p","d",1,"a".repeat(64),pages);String key=WordRenderingService.cacheKey(a,"renderer-v1");assertNotEquals(key,WordRenderingService.cacheKey(doc("other","d",1,a.sha256(),pages),"renderer-v1"));assertNotEquals(key,WordRenderingService.cacheKey(doc("p","d",2,a.sha256(),pages),"renderer-v1"));assertNotEquals(key,WordRenderingService.cacheKey(a,"renderer-v2"));assertNotEquals(key,WordRenderingService.cacheKey(doc("p","d",1,a.sha256(),List.of(new Domain.Page(1,"改变正文","BLOCK","POI_NATIVE",""))),"renderer-v1"));}
    @Test void originalBlockMappingRequiresUniqueTextAndNeverInventsWordPages(){var d=doc("p","d",1,"a".repeat(64),List.of(new Domain.Page(1,"重复","BLOCK","POI_NATIVE",""),new Domain.Page(2,"重复","BLOCK","POI_NATIVE",""),new Domain.Page(3,"唯一正文","BLOCK","POI_NATIVE","")));var unique=map("text","唯一正文","startRenderedPage",7,"physicalPage",null);var duplicate=map("text","重复","startRenderedPage",8,"physicalPage",null);var result=map("spans",List.of(unique,duplicate));WordRenderingService.bindBlocks(result,d);assertEquals(3,unique.get("documentBlock"));assertNull(duplicate.get("documentBlock"));assertNull(unique.get("physicalPage"));assertEquals(7,unique.get("startRenderedPage"));}
    @Test void externalImageAndTemplateRelationshipsAreBlockedBeforeSdkLoad(){String external="<Relationships><Relationship Type='image' TargetMode='External' Target='http://127.0.0.1/private'/></Relationships>";assertEquals("RESOURCE_BLOCKED",assertThrows(IOException.class,()->validateXml(external.getBytes(StandardCharsets.UTF_8),true)).getMessage());assertDoesNotThrow(()->validateXml(external.replace("Type='image'","Type='https://example.test/hyperlink'").getBytes(StandardCharsets.UTF_8),true));}
    @Test void externalEntitiesAndExcessiveNestingAreRejected(){assertThrows(IOException.class,()->validateXml("<!DOCTYPE a [<!ENTITY x SYSTEM 'file:///secret'>]><a>&x;</a>".getBytes(StandardCharsets.UTF_8),false));assertThrows(IOException.class,()->validateXml(("<a>".repeat(70)+"</a>".repeat(70)).getBytes(StandardCharsets.UTF_8),false));}
    @Test void macroPackagesAreRejected()throws Exception{Path zip=temp.resolve("macro.docx");try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(zip))){out.putNextEntry(new ZipEntry("word/vbaProject.bin"));out.write(new byte[]{1});out.closeEntry();}assertEquals("WORD_MACROS_UNSUPPORTED",assertThrows(IOException.class,()->validateDocx(zip)).getMessage());}
    @Test void realOoxmlPackagePassesPreflightWithoutChangingOriginal()throws Exception{Path source=temp.resolve("safe.docx");try(XWPFDocument d=new XWPFDocument()){d.createParagraph().createRun().setText("合成资料");try(OutputStream out=Files.newOutputStream(source)){d.write(out);}}String before=hash(source,1_000_000);validateDocx(source);assertEquals(before,hash(source,1_000_000));}
    @Test void cleanupCannotEscapeItsCacheRootAndOutputIsBounded()throws Exception{Path outside=Files.createTempFile(temp,"keep-",".txt");Files.writeString(outside,"keep");assertThrows(IOException.class,()->clear(outside,temp.resolve("cache")));assertEquals("keep",Files.readString(outside));try(var out=new LimitedOutput(new ByteArrayOutputStream(),2)){assertThrows(IOException.class,()->out.write(new byte[3]));}}
    @Test void sdkParagraphAndMergedCellMappingsKeepNodeRangesSeparateFromBboxes()throws Exception{
        // Evaluation SDK use is confined to this synthetic in-memory API contract test, never the production evidence path.
        Document d=new Document();DocumentBuilder b=new DocumentBuilder(d);b.writeln("First synthetic paragraph");b.insertBreak(BreakType.PAGE_BREAK);b.writeln("Second synthetic paragraph");b.startTable();b.insertCell();b.getCellFormat().setHorizontalMerge(CellMerge.FIRST);b.write("Merged synthetic heading");b.insertCell();b.getCellFormat().setHorizontalMerge(CellMerge.PREVIOUS);b.endRow();b.endTable();LayoutCollector collector=new LayoutCollector(d);d.updatePageLayout();
        var spans=WordRenderWorker.structure(d,collector,"synthetic",System.nanoTime()+TimeUnit.SECONDS.toNanos(30));var second=spans.stream().filter(s->str(s,"text").contains("Second synthetic paragraph")).findFirst().orElseThrow();assertTrue(((Number)second.get("endRenderedPage")).intValue()>=2,"page range="+second);assertNull(second.get("bbox"));assertNull(second.get("physicalPage"));assertTrue(second.containsKey("layoutAnchor"),"anchor="+second);var cells=spans.stream().filter(s->"TABLE_CELL".equals(s.get("kind"))).toList();assertFalse(cells.isEmpty());assertTrue(cells.stream().anyMatch(s->str(s,"text").contains("Merged synthetic heading")));assertTrue(cells.stream().allMatch(s->s.containsKey("horizontalMerge")&&s.get("columnSpan")==null));assertTrue(cells.stream().allMatch(s->s.get("column")==null));
    }
    @Test void sdkRenderedSpanEnumerationIncludesLaterPages()throws Exception{Document d=new Document();DocumentBuilder b=new DocumentBuilder(d);b.write("ALPHA");b.insertBreak(BreakType.PAGE_BREAK);b.write("OMEGA");d.updatePageLayout();List<Map<String,Object>> pages=new ArrayList<>();for(int i=0;i<d.getPageCount();i++)pages.add(map("width",d.getPageInfo(i).getWidthInPoints(),"height",d.getPageInfo(i).getHeightInPoints()));var spans=WordRenderWorker.renderedSpans(d,"synthetic",System.nanoTime()+TimeUnit.SECONDS.toNanos(30),pages);var tail=spans.stream().filter(s->str(s,"text").contains("OMEGA")).findFirst().orElseThrow();assertTrue(((Number)tail.get("renderedPage")).intValue()>=2);assertEquals("RENDERED_PAGE",tail.get("locationType"));assertNotNull(tail.get("bbox"));assertNull(tail.get("printedPage"));}
    @Test void realIsolatedWorkerRejectsInvalidLicenseWithoutPdf()throws Exception{Path license=temp.resolve("bad.lic");Files.writeString(license,"invalid");var request=map("licensePath",license.toString(),"licenseHash",hash(Files.readAllBytes(license)),"outputDirectory",temp.toString());assertEquals("COMPLETE",new WordRenderingService.ProcessWorker().execute(request,temp,20));Map<?,?> result=JSON.readValue(Files.readAllBytes(temp.resolve("result.json")),Map.class);assertEquals("LICENSE_INVALID",result.get("status"));assertFalse(Files.exists(temp.resolve("rendered.pdf")));}
    @Test void isolatedWorkerHasHardTimeout()throws Exception{assertTimeoutPreemptively(Duration.ofSeconds(8),()->assertEquals("TIMEOUT",WordRenderingService.ProcessWorker.launch(sleeperCommand(),Map.of(),temp,1)));}
    @Test void isolatedWorkerCancellationInterruptsWaitAndKeepsInterruptFlag()throws Exception{AtomicReference<Throwable> error=new AtomicReference<>();CountDownLatch started=new CountDownLatch(1);Thread worker=new Thread(()->{started.countDown();try{WordRenderingService.ProcessWorker.launch(sleeperCommand(),Map.of(),temp,30);}catch(Throwable e){error.set(e);assertTrue(Thread.currentThread().isInterrupted());}});worker.start();started.await();Thread.sleep(300);worker.interrupt();worker.join(5000);assertFalse(worker.isAlive());assertInstanceOf(InterruptedIOException.class,error.get());}
    private List<String> sleeperCommand()throws IOException{List<String> args=new ArrayList<>(WordRenderingService.ProcessWorker.command());args.set(args.size()-1,Sleeper.class.getName());return args;}
    public static final class Sleeper{public static void main(String[] args)throws Exception{System.in.readAllBytes();Thread.sleep(30_000);}}
    public static final class NoInputReader{public static void main(String[] args)throws Exception{Thread.sleep(30_000);}}
    @Test void hardDeadlineAlsoCoversBlockedChildStdin()throws Exception{
        var args=new ArrayList<>(WordRenderingService.ProcessWorker.command());args.set(args.size()-1,NoInputReader.class.getName());
        assertTimeoutPreemptively(Duration.ofSeconds(6),()->assertEquals("TIMEOUT",WordRenderingService.ProcessWorker.launch(args,Map.of("boundedInput","x".repeat(60_000)),temp,1)));
    }
    @Test void excessiveRequestsAreRejectedBeforeProcessCreation()throws Exception{
        var error=assertThrows(IOException.class,()->WordRenderingService.ProcessWorker.launch(List.of("not-an-executable"),Map.of("large","x".repeat(65536)),temp,1));
        assertEquals("WORD_REQUEST_LIMIT",error.getMessage());assertFalse(Files.exists(temp.resolve("worker.args")));
    }
    @Test @EnabledIfEnvironmentVariable(named="BIDCHECK_WORD_LICENSE_PATH",matches=".+") void licensedSyntheticRenderAndCacheRoundTrip()throws Exception{
        Path source=temp.resolve("licensed.docx");try(XWPFDocument d=new XWPFDocument()){d.createParagraph().createRun().setText("Licensed synthetic paragraph");try(OutputStream out=Files.newOutputStream(source)){d.write(out);}}var document=doc("p","d",1,hash(source,1_000_000),List.of(new Domain.Page(1,"Licensed synthetic paragraph","PARAGRAPH","POI_NATIVE","")));var service=new WordRenderingService(temp.toString(),System.getenv("BIDCHECK_WORD_LICENSE_PATH"),true,10,60,"");var layout=service.layout(document,source);assertEquals("COMPLETE",layout.get("status"),JSON.writeValueAsString(layout));assertEquals(true,layout.get("usableForEvidence"));assertEquals(true,service.layout(document,source).get("cached"));byte[] image=service.renderPage(document,source,1);assertArrayEquals(new byte[]{(byte)137,80,78,71},Arrays.copyOf(image,4));assertEquals(layout.get("derivedSha256"),hash(service.renderedPdf(document,source),MAX_PDF_BYTES));
    }
}
